import numpy as np
import pandas as pd
from collections import Counter

class DecisionTree:
    def __init__(self, max_depth=5):
        self.max_depth = max_depth
        self.tree = {}

    def fit(self, X, y, depth=0):
        if depth >= self.max_depth or len(np.unique(y)) == 1 or len(y) < 2:
            self.tree = np.mean(y)
            return

        best_gini = float('inf')
        best_split = None

        # subsample features for speed
        n_features = X.shape[1]
        features = np.random.choice(n_features, int(np.sqrt(n_features)), replace=False)

        for j in features:
            thresholds = np.percentile(X[:, j], [20, 40, 60, 80])
            for t in thresholds:
                left_mask = X[:, j] <= t
                right_mask = ~left_mask

                if np.sum(left_mask) == 0 or np.sum(right_mask) == 0:
                    continue

                p_left = np.mean(y[left_mask])
                p_right = np.mean(y[right_mask])

                # Gini impurity for binary classification: p * (1-p)
                gini_left = p_left * (1 - p_left) * np.sum(left_mask)
                gini_right = p_right * (1 - p_right) * np.sum(right_mask)
                gini = gini_left + gini_right

                if gini < best_gini:
                    best_gini = gini
                    best_split = (j, t, left_mask, right_mask)

        if best_split is None:
            self.tree = np.mean(y)
            return

        j, t, left_mask, right_mask = best_split
        self.tree = {'feature': j, 'threshold': t, 'left': DecisionTree(self.max_depth), 'right': DecisionTree(self.max_depth)}
        self.tree['left'].fit(X[left_mask], y[left_mask], depth + 1)
        self.tree['right'].fit(X[right_mask], y[right_mask], depth + 1)

    def predict_row(self, row, node):
        if not isinstance(node, dict):
            return node
        if row[node['feature']] <= node['threshold']:
            return self.predict_row(row, node['left'].tree)
        else:
            return self.predict_row(row, node['right'].tree)

    def predict(self, X):
        return np.array([self.predict_row(row, self.tree) for row in X])

df = pd.read_csv('train.csv').head(10000)
y = df['target'].values
X = df.drop(columns=['target']).values

np.random.seed(42)
trees = []
for i in range(10):
    print(f"Training tree {i}...")
    idx = np.random.choice(len(X), len(X), replace=True)
    tree = DecisionTree(max_depth=5)
    tree.fit(X[idx], y[idx])
    trees.append(tree)

preds = np.zeros(len(X))
for tree in trees:
    preds += tree.predict(X)
preds /= len(trees)

print("RF Train acc:", ((preds > 0.5) == y).mean())
